-- openshop:framework 0002_openshop_queue_indexes
-- Generated by `openshop migrate generate`. Review before applying.

-- The worker reads the queue through these indexes. Their predicates repeat the
-- conditions of its statements, which is what lets PostgreSQL use them.

-- Claiming: the runs that can be leased, in the order they are claimed.
CREATE INDEX IF NOT EXISTS flow_runs_claimable_idx ON flow_runs (available_at, created_at)
  WHERE status IN ('pending', 'sleeping', 'running');

-- Deadline expiry: the unfinished runs that have a deadline.
CREATE INDEX IF NOT EXISTS flow_runs_deadline_idx ON flow_runs (deadline_at)
  WHERE status IN ('pending', 'sleeping', 'running') AND deadline_at IS NOT NULL;
